import React, { useEffect, useState } from "react";
import axios from "axios";
import Carousel from "react-bootstrap/Carousel";

const Caroussel = () => {
  const [data, setData] = useState([]);
  const [index, setIndex] = useState(0);

  // Fetch les données au montage du composant
  useEffect(() => {
    axios
      .get(
        "https://api.themoviedb.org/3/movie/now_playing?api_key=864b6602f4018630491e67fa714381e6&language=fr-FR"
      )
      .then((res) => setData(res.data.results))
      .catch((error) =>
        console.error("Erreur lors de la récupération des films:", error)
      );
  }, []);

  // Fonction pour mettre à jour l'index actif
  const handleSelect = (selectedIndex) => {
    setIndex(selectedIndex);
  };

  return (
    <div className="carousel-container">
      <Carousel
        activeIndex={index}
        onSelect={handleSelect}
        interval={5000}
        indicators={false}
        controls={true}
      >
        {data
          ?.filter((movie) =>
            ["en", "fr", "jp", "ko"].includes(movie.original_language)
          )
          .map((movie, idx) => (
            <Carousel.Item key={idx}>
              <img
                className="d-block w-100"
                src={
                  movie.backdrop_path
                    ? "https://image.tmdb.org/t/p/original" +
                      movie.backdrop_path
                    : "./img/default-image.jpeg" // Image par défaut si backdrop_path est null
                }
                alt={movie.title}
              />
              <Carousel.Caption>
                <h3>{movie.title}</h3>
                <p>{movie.overview}</p>
              </Carousel.Caption>
            </Carousel.Item>
          ))}
      </Carousel>
    </div>
  );
};

export default Caroussel;
